use vstd::prelude::*;

verus! {

/// A simple closed interval [a, b].
/// We keep it concrete (f32 fields) and specify exact equality in postconditions.
pub struct Interval {
    pub a: f32,
    pub b: f32,
}

/// A Laguerre “series object” that stores coefficients and two intervals.
pub struct Laguerre {
    pub coefficients: Vec<f32>,
    pub domain: Interval,
    pub window: Interval,
}

/// Construct a Laguerre object from the given coefficients.
/// - Stores the coefficients exactly (same order/values).
/// - Sets domain = window = [0.0, 1.0].
fn make_laguerre(coefficients: Vec<f32>) -> (out: Laguerre)
    ensures
        // interval fields are exactly the unit interval
        out.domain.a == 0.0f32,
        out.domain.b == 1.0f32,
        out.window.a == 0.0f32,
        out.window.b == 1.0f32,

        // coefficients are preserved elementwise
        out.coefficients.len() == coefficients.len(),
        forall|i: int|
            0 <= i < coefficients.len() ==> out.coefficients[i] == coefficients[i],
{
    let domain = Interval { a: 0.0f32, b: 1.0f32 };
    let window = Interval { a: 0.0f32, b: 1.0f32 };

    // Move the input vector into the output so it is preserved exactly.
    Laguerre { coefficients, domain, window }
}

} // verus!

